    IS 'Código de falha informado pelo inversor; abre alerta FALHA_INVERSOR automaticamente.';

COMMENT ON COLUMN public.string_performance_measurement.data_source
    IS 'SENSOR (inversor real) ou SIMULATOR (simulador do contrato de dados).';

CREATE TABLE IF NOT EXISTS public.sungrow_credential
(
    id smallint NOT NULL DEFAULT 1,
    access_token text COLLATE pg_catalog."default" NOT NULL,
    refresh_token text COLLATE pg_catalog."default" NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    authorized_plants text COLLATE pg_catalog."default",
    updated_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT sungrow_credential_pkey PRIMARY KEY (id),
    CONSTRAINT ck_sungrow_credential_single_row CHECK (id = 1)
);

COMMENT ON TABLE public.sungrow_credential
    IS 'Tokens da API aberta da Sungrow (iSolarCloud), uma unica linha. O refresh token e substituido a cada renovação; por isso fica persistido.';

COMMENT ON COLUMN public.sungrow_credential.authorized_plants
    IS 'Ids das plantas autorizadas pelo dono (auth_ps_list), separados por vírgula.';

CREATE TABLE IF NOT EXISTS public.suggested_external_relocation
(
    id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY ( INCREMENT 1 START 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 ),
    panel_id bigint NOT NULL,
    destination_company_id bigint NOT NULL,
    segment_id bigint NOT NULL,
    requested_by uuid NOT NULL,
    reviewed_by uuid,
    justification text COLLATE pg_catalog."default" NOT NULL,
    status character varying(20) COLLATE pg_catalog."default" NOT NULL DEFAULT 'PENDENTE'::character varying,
    suggested_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reviewed_at timestamp with time zone,
    CONSTRAINT suggested_external_relocation_pkey PRIMARY KEY (id)
);

COMMENT ON TABLE public.suggested_external_relocation
    IS 'Sugestão, registrada pelo operador, de destinar uma placa a outra empresa (segunda vida).';

CREATE TABLE IF NOT EXISTS public.suggested_internal_relocation
(
    id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY ( INCREMENT 1 START 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 ),
    string_id uuid NOT NULL,
    quantity integer NOT NULL,
    suggested_unit_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    reviewed_by uuid,
    justification text COLLATE pg_catalog."default" NOT NULL,
    status character varying(20) COLLATE pg_catalog."default" NOT NULL DEFAULT 'PENDENTE'::character varying,
    suggested_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reviewed_at timestamp with time zone,
    CONSTRAINT suggested_internal_relocation_pkey PRIMARY KEY (id)
);

COMMENT ON TABLE public.suggested_internal_relocation
    IS 'Sugestão, registrada pelo operador, de mover placas de uma string para outra filial da mesma empresa.';

CREATE TABLE IF NOT EXISTS public.warning
(
    id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY ( INCREMENT 1 START 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 ),
    string_id uuid,
    panel_id bigint,
    type character varying(30) COLLATE pg_catalog."default" NOT NULL,
    severity character varying(10) COLLATE pg_catalog."default" NOT NULL DEFAULT 'MEDIA'::character varying,
    status character varying(20) COLLATE pg_catalog."default" NOT NULL DEFAULT 'ATIVO'::character varying,
    message text COLLATE pg_catalog."default" NOT NULL,
    reported_by uuid,
    generation_dt timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at timestamp with time zone,
    CONSTRAINT warning_pkey PRIMARY KEY (id)
);

COMMENT ON TABLE public.warning
    IS 'Alerta automático da string (baixa eficiência ou falha do inversor) ou relato de campo do técnico sobre uma placa.';

COMMENT ON COLUMN public.warning.severity
    IS 'BAIXA, MEDIA, ALTA ou CRITICA; define a prioridade da OS gerada.';

COMMENT ON COLUMN public.warning.status
    IS 'ATIVO; RECONHECIDO quando vira OS; RESOLVIDO quando a OS é concluída ou a saúde volta ao normal.';

