-- Apollo | Neon | INCREMENTAL e IDEMPOTENTE (pode rodar varias vezes; NAO apaga dados)
-- Pre-requisito: tabelas do "Script_SQL_-_Apollo_-_Completo_-_Novo" ja existem.
-- Faz: colunas faltantes, schema audit, views vw_*, funcoes, triggers, procedures pr_*, indices,
--      idempotencia, tokens push e notificacoes (+ trigger que cria notificacao ao abrir OS).
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS audit;

-- ===== Colunas / tabelas novas =====

-- 1) Corrige o erro do Spring: missing column [is_first_access] in table [employee]
ALTER TABLE public.employee ADD COLUMN IF NOT EXISTS is_first_access boolean NOT NULL DEFAULT true;
ALTER TABLE public.employee ADD COLUMN IF NOT EXISTS fcm_token varchar(300);

-- 2) Endereco: desativar em vez de excluir
ALTER TABLE public.address ADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true;

-- 3) Idempotencia (header Idempotency-Key)
CREATE TABLE IF NOT EXISTS public.idempotency_key (
  id               uuid NOT NULL DEFAULT gen_random_uuid(),
  employee_id      uuid NOT NULL,
  idem_key         varchar(128) NOT NULL,
  http_method      varchar(10)  NOT NULL,
  request_path     varchar(300) NOT NULL,
  request_hash     varchar(64)  NOT NULL,
  response_status  integer,
  response_body    text,
  created_at       timestamptz NOT NULL DEFAULT now(),
  expires_at       timestamptz NOT NULL DEFAULT now() + interval '24 hours',
  CONSTRAINT idempotency_key_pkey PRIMARY KEY (id),
  CONSTRAINT ux_idempotency_employee_key UNIQUE (employee_id, idem_key),
  CONSTRAINT fk_idempotency_employee FOREIGN KEY (employee_id) REFERENCES public.employee(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_idempotency_expires ON public.idempotency_key (expires_at);

-- 4) Push: token FCM por dispositivo
CREATE TABLE IF NOT EXISTS public.device_push_token (
  id            uuid NOT NULL DEFAULT gen_random_uuid(),
  employee_id   uuid NOT NULL,
  platform      varchar(10)  NOT NULL,            -- WEB | ANDROID
  device_name   varchar(80),
  fcm_token     varchar(300) NOT NULL,
  is_active     boolean NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now(),
  last_seen_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT device_push_token_pkey PRIMARY KEY (id),
  CONSTRAINT ux_device_push_token UNIQUE (fcm_token),
  CONSTRAINT ck_device_push_platform CHECK (platform IN ('WEB','ANDROID')),
  CONSTRAINT fk_push_token_employee FOREIGN KEY (employee_id) REFERENCES public.employee(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_push_token_employee ON public.device_push_token (employee_id) WHERE is_active;

-- 5) Notificacao (gerada ao abrir uma OS) + status de envio
CREATE TABLE IF NOT EXISTS public.notification (
  id                    uuid NOT NULL DEFAULT gen_random_uuid(),
  employee_id           uuid NOT NULL,            -- destinatario
  maintenance_register_id bigint,                 -- OS de origem
  type                  varchar(30)  NOT NULL DEFAULT 'SERVICE_ORDER_OPENED',
  title                 varchar(120) NOT NULL,
  body                  varchar(500) NOT NULL,
  is_read               boolean NOT NULL DEFAULT false,
  read_at               timestamptz,
  push_status           varchar(12) NOT NULL DEFAULT 'PENDING',  -- PENDING | SENT | FAILED | SKIPPED
  push_error            varchar(300),
  push_sent_at          timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT notification_pkey PRIMARY KEY (id),
  CONSTRAINT ck_notification_push_status CHECK (push_status IN ('PENDING','SENT','FAILED','SKIPPED')),
  CONSTRAINT fk_notification_employee FOREIGN KEY (employee_id) REFERENCES public.employee(id) ON DELETE CASCADE,
  CONSTRAINT fk_notification_register FOREIGN KEY (maintenance_register_id) REFERENCES public.maintenance_register(id) ON DELETE SET NULL,
  -- uma notificacao por OS e destinatario: evita duplicar em retry
  CONSTRAINT ux_notification_register_employee UNIQUE (maintenance_register_id, employee_id, type)
);
CREATE INDEX IF NOT EXISTS ix_notification_employee_unread ON public.notification (employee_id, created_at DESC) WHERE NOT is_read;

-- ===== Auditoria =====
CREATE TABLE IF NOT EXISTS audit.audit_panel (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    operation           varchar(10)  NOT NULL,
    operation_timestamp timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    database_user       varchar(100) NOT NULL,
    panel_id            bigint,
    old_data            jsonb,
    new_data            jsonb,
    transaction_id      bigint       NOT NULL DEFAULT txid_current(),
    CONSTRAINT ck_audit_panel_operation CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE'))
);

CREATE TABLE IF NOT EXISTS audit.audit_maintenance_register (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    operation           varchar(10)  NOT NULL,
    operation_timestamp timestamptz  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    database_user       varchar(100) NOT NULL,
    maintenance_id      bigint,
    old_data            jsonb,
    new_data            jsonb,
    transaction_id      bigint       NOT NULL DEFAULT txid_current(),
    CONSTRAINT ck_audit_maintenance_operation CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE'))
);


-- ===== Views, funcoes, triggers e procedures (do script 2o ano) =====
DROP VIEW IF EXISTS vw_string_panels CASCADE;
DROP VIEW IF EXISTS vw_string_overview CASCADE;
DROP VIEW IF EXISTS vw_maintenance_order CASCADE;
DROP VIEW IF EXISTS vw_string_current_health CASCADE;
DROP VIEW IF EXISTS vw_company_unit_capacity CASCADE;
DROP VIEW IF EXISTS vw_string_capacity CASCADE;
DROP VIEW IF EXISTS vw_warning_target CASCADE;
DROP VIEW IF EXISTS vw_string_location CASCADE;
DROP VIEW IF EXISTS vw_auth_user CASCADE;

CREATE VIEW vw_auth_user AS
SELECT e.id AS user_id, e.company_unit_id, cu.company_id, e.full_name, e.email, e.password_hash,
       e.role_id, r.name AS job_role, (e.is_active AND cu.is_active) AS is_active, e.is_first_access, e.fcm_token, e.created_at
  FROM employee e
  JOIN roles r ON r.id = e.role_id
  JOIN company_unit cu ON cu.id = e.company_unit_id;

CREATE VIEW vw_string_location AS
SELECT s.id AS string_id, i.id AS inverter_id, i.company_unit_id, cu.company_id
  FROM string s
  JOIN inverter i ON i.id = s.inverter_id
  JOIN company_unit cu ON cu.id = i.company_unit_id;

CREATE VIEW vw_warning_target AS
SELECT w.id AS warning_id, COALESCE(w.string_id, p.string_id) AS string_id, l.inverter_id, l.company_unit_id, l.company_id
  FROM warning w
  LEFT JOIN panel p ON p.id = w.panel_id
  JOIN vw_string_location l ON l.string_id = COALESCE(w.string_id, p.string_id);

CREATE VIEW vw_string_capacity AS
SELECT s.id AS string_id, s.inverter_id, pm.pmax_w,
       count(p.id) FILTER (WHERE p.operating_stats IN ('OPERACIONAL', 'MANUTENCAO', 'FALHA')) AS installed_panels,
       count(p.id) FILTER (WHERE p.operating_stats IN ('OPERACIONAL', 'MANUTENCAO', 'FALHA')) * pm.pmax_w AS nominal_power_wp
  FROM string s
  JOIN panel_model pm ON pm.id = s.panel_model_id
  LEFT JOIN panel p ON p.string_id = s.id
 GROUP BY s.id, s.inverter_id, pm.pmax_w;

CREATE VIEW vw_company_unit_capacity AS
SELECT cu.id AS company_unit_id, round(COALESCE(sum(c.nominal_power_wp), 0) / 1000.0, 2) AS kwp_total
  FROM company_unit cu
  LEFT JOIN inverter i ON i.company_unit_id = cu.id
  LEFT JOIN vw_string_capacity c ON c.inverter_id = i.id
 GROUP BY cu.id;

CREATE VIEW vw_string_current_health AS
SELECT DISTINCT ON (h.string_id) h.string_id, h.calculated_at, h.health_score, h.sibling_ratio, h.nominal_ratio, h.warning_penalty
  FROM string_health_history h
 ORDER BY h.string_id, h.calculated_at DESC;

CREATE VIEW vw_maintenance_order AS
SELECT mr.*, t.string_id, t.inverter_id, t.company_unit_id, w.severity AS priority, w.type AS warning_type,
       COALESCE(pc.parts_cost, 0) AS parts_cost,
       COALESCE(mr.labor_cost, 0) + COALESCE(pc.parts_cost, 0) AS total_cost,
       CASE WHEN mr.maintenance_status IN ('ABERTA', 'EM_ANDAMENTO') AND mr.due_date IS NOT NULL
             AND CURRENT_TIMESTAMP > mr.due_date THEN 'ATRASADA'
            ELSE mr.maintenance_status END AS calculated_status
  FROM maintenance_register mr
  JOIN warning w ON w.id = mr.warning_id
  JOIN vw_warning_target t ON t.warning_id = mr.warning_id
  LEFT JOIN (SELECT maintenance_id, sum(quantity * COALESCE(unit_cost, 0)) AS parts_cost
               FROM maintenance_part GROUP BY maintenance_id) pc ON pc.maintenance_id = mr.id;

CREATE VIEW vw_string_overview AS
SELECT s.id AS string_id, i.company_unit_id, s.code, s.invoice_number, pm.manufacturer, pm.model,
       s.purchased_qty, c.installed_panels, c.nominal_power_wp, round(c.nominal_power_wp / 1000.0, 2) AS nominal_power_kwp,
       s.status, h.health_score, h.calculated_at AS health_calculated_at,
       i.code AS inverter_code, s.mppt_number, s.entry_number,
       (SELECT count(*) FROM panel p WHERE p.string_id = s.id AND p.operating_stats = 'OPERACIONAL') AS panels_operational,
       (SELECT count(*) FROM panel p WHERE p.string_id = s.id AND p.operating_stats = 'MANUTENCAO') AS panels_in_maintenance,
       (SELECT count(*) FROM panel p WHERE p.string_id = s.id AND p.operating_stats = 'EM_ESTOQUE') AS panels_in_stock,
       (SELECT count(*) FROM warning w JOIN vw_warning_target t ON t.warning_id = w.id
         WHERE t.string_id = s.id AND w.status <> 'RESOLVIDO') AS active_warnings,
       (SELECT max(m.measured_at) FROM string_performance_measurement m WHERE m.string_id = s.id) AS last_measurement_at
  FROM string s
  JOIN inverter i ON i.id = s.inverter_id
  JOIN panel_model pm ON pm.id = s.panel_model_id
  JOIN vw_string_capacity c ON c.string_id = s.id
  LEFT JOIN vw_string_current_health h ON h.string_id = s.id;

CREATE VIEW vw_string_panels AS
SELECT p.id AS panel_id, p.string_id, i.company_unit_id, s.code AS string_code, i.code AS inverter_code,
       p.serial_number, p.barcode, pm.manufacturer, pm.model, p.operating_stats, p.installation_dt, p.activated_at,
       h.health_score AS string_health_score,
       (SELECT count(*) FROM warning w WHERE w.panel_id = p.id AND w.status <> 'RESOLVIDO') AS active_panel_warnings
  FROM panel p
  JOIN string s ON s.id = p.string_id
  JOIN inverter i ON i.id = s.inverter_id
  JOIN panel_model pm ON pm.id = s.panel_model_id
  LEFT JOIN vw_string_current_health h ON h.string_id = s.id;
CREATE OR REPLACE FUNCTION fn_role_of(p_employee_id uuid)
RETURNS varchar LANGUAGE sql STABLE AS $$
    SELECT r.name FROM employee e JOIN roles r ON r.id = e.role_id WHERE e.id = p_employee_id AND e.is_active;
$$;

CREATE OR REPLACE FUNCTION fn_company_of_employee(p_employee_id uuid)
RETURNS bigint LANGUAGE sql STABLE AS $$
    SELECT cu.company_id FROM employee e JOIN company_unit cu ON cu.id = e.company_unit_id WHERE e.id = p_employee_id;
$$;

CREATE OR REPLACE FUNCTION audit.fn_audit_panel()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO audit.audit_panel (operation, database_user, panel_id, old_data, new_data)
    VALUES (TG_OP, CURRENT_USER, COALESCE(NEW.id, OLD.id),
            CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) END,
            CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) END);
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION audit.fn_audit_maintenance_register()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO audit.audit_maintenance_register (operation, database_user, maintenance_id, old_data, new_data)
    VALUES (TG_OP, CURRENT_USER, COALESCE(NEW.id, OLD.id),
            CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) END,
            CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) END);
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION fn_validate_employee()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_role         varchar;
    v_creator_role varchar;
    v_creator_unit uuid;
BEGIN
    SELECT name INTO v_role FROM roles WHERE id = NEW.role_id;
    IF v_role = 'GERENTE' THEN
        IF NEW.source_id IS NULL THEN
            RAISE EXCEPTION 'Gerente só é cadastrado pelo administrador no CRUD do 1º ano e chega pelo RPA';
        END IF;
    ELSE
        IF NEW.created_by IS NULL THEN
            RAISE EXCEPTION 'Analista, operador e técnico são cadastrados pelo gerente da filial';
        END IF;
        SELECT fn_role_of(NEW.created_by), company_unit_id INTO v_creator_role, v_creator_unit
          FROM employee WHERE id = NEW.created_by;
        IF v_creator_role IS DISTINCT FROM 'GERENTE' OR v_creator_unit IS DISTINCT FROM NEW.company_unit_id THEN
            RAISE EXCEPTION 'O cadastro deve ser feito por um gerente ativo da mesma filial';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION fn_validate_inverter()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF fn_role_of(NEW.created_by) IS DISTINCT FROM 'OPERADOR'
       OR (SELECT company_unit_id FROM employee WHERE id = NEW.created_by) IS DISTINCT FROM NEW.company_unit_id THEN
        RAISE EXCEPTION 'Inversor só pode ser cadastrado por um operador ativo da própria filial';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION fn_validate_string()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_unit       uuid;
    v_mppt_count smallint;
    v_per_mppt   smallint;
    v_code       varchar;
BEGIN
    SELECT i.company_unit_id, im.mppt_count, im.strings_per_mppt, i.code
      INTO v_unit, v_mppt_count, v_per_mppt, v_code
      FROM inverter i JOIN inverter_model im ON im.id = i.inverter_model_id
     WHERE i.id = NEW.inverter_id;
    IF NEW.mppt_number > v_mppt_count THEN
        RAISE EXCEPTION 'MPPT % fora do intervalo 1..% do inversor %', NEW.mppt_number, v_mppt_count, v_code;
    END IF;
    IF NEW.entry_number > v_per_mppt THEN
        RAISE EXCEPTION 'Entrada % fora do intervalo 1..% do MPPT', NEW.entry_number, v_per_mppt;
    END IF;
    IF TG_OP = 'INSERT' AND (fn_role_of(NEW.created_by) IS DISTINCT FROM 'OPERADOR'
       OR (SELECT company_unit_id FROM employee WHERE id = NEW.created_by) IS DISTINCT FROM v_unit) THEN
        RAISE EXCEPTION 'String só pode ser cadastrada por um operador ativo da filial do inversor';
    END IF;
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION fn_track_panel_status()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' OR OLD.operating_stats IS DISTINCT FROM NEW.operating_stats THEN
        INSERT INTO panel_status_history (panel_id, old_status, new_status, changed_at, changed_by)
        VALUES (NEW.id, CASE WHEN TG_OP = 'UPDATE' THEN OLD.operating_stats END, NEW.operating_stats,
                COALESCE(NEW.updated_at, CURRENT_TIMESTAMP), CURRENT_USER);
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION fn_measurement_fault_warning()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.fault_code IS NOT NULL AND btrim(NEW.fault_code) <> ''
       AND (TG_OP = 'INSERT' OR OLD.fault_code IS DISTINCT FROM NEW.fault_code)
       AND NOT EXISTS (SELECT 1 FROM warning w WHERE w.string_id = NEW.string_id
                          AND w.type = 'FALHA_INVERSOR' AND w.status <> 'RESOLVIDO') THEN
        INSERT INTO warning (string_id, type, severity, status, message, generation_dt)
        VALUES (NEW.string_id, 'FALHA_INVERSOR', 'CRITICA', 'ATIVO',
                format('Inversor reportou o código de falha %s na leitura de %s', NEW.fault_code,
                       to_char(NEW.measured_at AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI')),
                NEW.measured_at);
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION fn_validate_maintenance()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_company bigint;
BEGIN
    SELECT company_id INTO v_company FROM vw_warning_target WHERE warning_id = NEW.warning_id;
    IF fn_role_of(NEW.technician_id) IS DISTINCT FROM 'TECNICO' THEN
        RAISE EXCEPTION 'O responsável pela OS deve ser um técnico ativo';
    END IF;
    IF TG_OP = 'INSERT' AND fn_role_of(NEW.created_by) IS DISTINCT FROM 'OPERADOR' THEN
        RAISE EXCEPTION 'Somente o operador abre OS';
    END IF;
    IF v_company IS DISTINCT FROM fn_company_of_employee(NEW.technician_id)
       OR v_company IS DISTINCT FROM fn_company_of_employee(NEW.created_by) THEN
        RAISE EXCEPTION 'Alerta, técnico e operador da OS devem pertencer à mesma empresa';
    END IF;
    IF NEW.parent_maintenance_id IS NOT NULL AND v_company IS DISTINCT FROM (
        SELECT t.company_id FROM maintenance_register p JOIN vw_warning_target t ON t.warning_id = p.warning_id
         WHERE p.id = NEW.parent_maintenance_id) THEN
        RAISE EXCEPTION 'A OS de origem pertence a outra empresa';
    END IF;
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION fn_consume_maintenance_part()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_status    varchar;
    v_unit      uuid;
    v_available integer;
    v_cost      numeric(12,2);
BEGIN
    SELECT mr.maintenance_status, t.company_unit_id INTO v_status, v_unit
      FROM maintenance_register mr JOIN vw_warning_target t ON t.warning_id = mr.warning_id
     WHERE mr.id = NEW.maintenance_id;
    IF v_status NOT IN ('ABERTA', 'EM_ANDAMENTO') THEN
        RAISE EXCEPTION 'Peças só podem ser lançadas em OS aberta ou em andamento';
    END IF;
    SELECT available_qtt, unit_cost INTO v_available, v_cost
      FROM stock WHERE company_unit_id = v_unit AND part_id = NEW.part_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'A peça % não existe no estoque da filial', NEW.part_id; END IF;
    IF v_available < NEW.quantity THEN
        RAISE EXCEPTION 'Estoque insuficiente: % disponível, % solicitado', v_available, NEW.quantity;
    END IF;
    UPDATE stock SET available_qtt = available_qtt - NEW.quantity, updated_at = CURRENT_TIMESTAMP
     WHERE company_unit_id = v_unit AND part_id = NEW.part_id;
    NEW.unit_cost := COALESCE(NEW.unit_cost, v_cost);
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION fn_validate_internal_relocation()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_loc       record;
    v_dest_comp bigint;
    v_panels    integer;
BEGIN
    SELECT * INTO v_loc FROM vw_string_location WHERE string_id = NEW.string_id;
    SELECT company_id INTO v_dest_comp FROM company_unit WHERE id = NEW.suggested_unit_id;
    SELECT count(*) INTO v_panels FROM panel WHERE string_id = NEW.string_id AND operating_stats <> 'INATIVO';
    IF v_loc.company_id IS DISTINCT FROM v_dest_comp THEN
        RAISE EXCEPTION 'Realocação interna exige origem e destino na mesma empresa';
    END IF;
    IF v_loc.company_unit_id = NEW.suggested_unit_id THEN
        RAISE EXCEPTION 'A filial de destino deve ser diferente da filial atual da string';
    END IF;
    IF NEW.quantity > v_panels THEN
        RAISE EXCEPTION 'A quantidade (%) excede as % placas ativas da string', NEW.quantity, v_panels;
    END IF;
    IF TG_OP = 'INSERT' AND (fn_role_of(NEW.requested_by) IS DISTINCT FROM 'OPERADOR'
       OR fn_company_of_employee(NEW.requested_by) IS DISTINCT FROM v_loc.company_id) THEN
        RAISE EXCEPTION 'Sugestão de realocação só pode ser registrada por um operador da mesma empresa';
    END IF;
    IF NEW.reviewed_by IS NOT NULL AND fn_company_of_employee(NEW.reviewed_by) IS DISTINCT FROM v_loc.company_id THEN
        RAISE EXCEPTION 'O revisor deve pertencer à mesma empresa da string';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION fn_validate_external_relocation()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    v_company bigint;
BEGIN
    SELECT l.company_id INTO v_company FROM panel p JOIN vw_string_location l ON l.string_id = p.string_id WHERE p.id = NEW.panel_id;
    IF NEW.destination_company_id = v_company THEN
        RAISE EXCEPTION 'Realocação externa exige empresa de destino diferente da atual';
    END IF;
    IF TG_OP = 'INSERT' AND (fn_role_of(NEW.requested_by) IS DISTINCT FROM 'OPERADOR'
       OR fn_company_of_employee(NEW.requested_by) IS DISTINCT FROM v_company) THEN
        RAISE EXCEPTION 'Sugestão de realocação só pode ser registrada por um operador da empresa dona da placa';
    END IF;
    IF NEW.reviewed_by IS NOT NULL AND fn_company_of_employee(NEW.reviewed_by) IS DISTINCT FROM v_company THEN
        RAISE EXCEPTION 'O revisor deve pertencer à empresa dona da placa';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_validate_employee ON employee;
DROP TRIGGER IF EXISTS trg_validate_inverter ON inverter;
DROP TRIGGER IF EXISTS trg_validate_string ON string;
DROP TRIGGER IF EXISTS trg_audit_panel ON panel;
DROP TRIGGER IF EXISTS trg_track_panel_status ON panel;
DROP TRIGGER IF EXISTS trg_measurement_fault_warning ON string_performance_measurement;
DROP TRIGGER IF EXISTS trg_validate_maintenance ON maintenance_register;
DROP TRIGGER IF EXISTS trg_audit_maintenance_register ON maintenance_register;
DROP TRIGGER IF EXISTS trg_consume_maintenance_part ON maintenance_part;
DROP TRIGGER IF EXISTS trg_validate_internal_relocation ON suggested_internal_relocation;
DROP TRIGGER IF EXISTS trg_validate_external_relocation ON suggested_external_relocation;

CREATE TRIGGER trg_validate_employee
BEFORE INSERT OR UPDATE OF role_id, company_unit_id, created_by, source_id ON employee
FOR EACH ROW EXECUTE FUNCTION fn_validate_employee();

CREATE TRIGGER trg_validate_inverter
BEFORE INSERT OR UPDATE OF created_by, company_unit_id ON inverter
FOR EACH ROW EXECUTE FUNCTION fn_validate_inverter();

CREATE TRIGGER trg_validate_string
BEFORE INSERT OR UPDATE OF inverter_id, mppt_number, entry_number ON string
FOR EACH ROW EXECUTE FUNCTION fn_validate_string();

CREATE TRIGGER trg_audit_panel
AFTER INSERT OR UPDATE OR DELETE ON panel
FOR EACH ROW EXECUTE FUNCTION audit.fn_audit_panel();

CREATE TRIGGER trg_track_panel_status
AFTER INSERT OR UPDATE OF operating_stats ON panel
FOR EACH ROW EXECUTE FUNCTION fn_track_panel_status();

CREATE TRIGGER trg_measurement_fault_warning
AFTER INSERT OR UPDATE OF fault_code ON string_performance_measurement
FOR EACH ROW EXECUTE FUNCTION fn_measurement_fault_warning();

CREATE TRIGGER trg_validate_maintenance
BEFORE INSERT OR UPDATE OF technician_id, created_by, warning_id, parent_maintenance_id ON maintenance_register
FOR EACH ROW EXECUTE FUNCTION fn_validate_maintenance();

CREATE TRIGGER trg_audit_maintenance_register
AFTER INSERT OR UPDATE OR DELETE ON maintenance_register
FOR EACH ROW EXECUTE FUNCTION audit.fn_audit_maintenance_register();

CREATE TRIGGER trg_consume_maintenance_part
BEFORE INSERT ON maintenance_part
FOR EACH ROW EXECUTE FUNCTION fn_consume_maintenance_part();

CREATE TRIGGER trg_validate_internal_relocation
BEFORE INSERT OR UPDATE ON suggested_internal_relocation
FOR EACH ROW EXECUTE FUNCTION fn_validate_internal_relocation();

CREATE TRIGGER trg_validate_external_relocation
BEFORE INSERT OR UPDATE ON suggested_external_relocation
FOR EACH ROW EXECUTE FUNCTION fn_validate_external_relocation();

CREATE OR REPLACE FUNCTION fn_string_health_score(
    p_string_id uuid,
    p_window_days integer DEFAULT 7,
    p_as_of timestamptz DEFAULT CURRENT_TIMESTAMP,
    OUT health_score numeric(5,2),
    OUT sibling_ratio numeric(6,4),
    OUT nominal_ratio numeric(6,4),
    OUT warning_penalty numeric(5,2)
)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_inverter uuid;
    v_nominal  numeric;
    v_peak     numeric;
    v_since    timestamptz := p_as_of - make_interval(days => p_window_days);
BEGIN
    SELECT inverter_id, nominal_power_wp INTO v_inverter, v_nominal FROM vw_string_capacity WHERE string_id = p_string_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'String % não encontrada', p_string_id; END IF;
    warning_penalty := 0;
    IF v_nominal IS NULL OR v_nominal = 0 THEN RETURN; END IF;

    SELECT percentile_cont(0.95) WITHIN GROUP (ORDER BY m.power_w) INTO v_peak
      FROM string_performance_measurement m
     WHERE m.string_id = p_string_id AND m.measured_at > v_since AND m.measured_at <= p_as_of;
    IF v_peak IS NULL THEN RETURN; END IF;
    nominal_ratio := LEAST(1.0, v_peak / v_nominal);

    WITH siblings AS (
        SELECT c.string_id, c.nominal_power_wp
          FROM vw_string_capacity c JOIN string s ON s.id = c.string_id
         WHERE c.inverter_id = v_inverter AND c.nominal_power_wp > 0
           AND (s.status IN ('ATIVA', 'MANUTENCAO') OR s.id = p_string_id)
    ), win AS (
        SELECT m.string_id, m.measured_at, m.power_w / sb.nominal_power_wp AS norm
          FROM string_performance_measurement m JOIN siblings sb ON sb.string_id = m.string_id
         WHERE m.measured_at > v_since AND m.measured_at <= p_as_of
    ), agg AS (
        SELECT measured_at, sum(norm) AS total, count(*) AS n FROM win GROUP BY measured_at
    )
    SELECT avg(LEAST(1.0, w.norm / ((a.total - w.norm) / (a.n - 1)))) INTO sibling_ratio
      FROM win w JOIN agg a ON a.measured_at = w.measured_at
     WHERE w.string_id = p_string_id AND a.n > 1 AND a.total - w.norm > 0;

    SELECT COALESCE(sum(CASE w.severity WHEN 'CRITICA' THEN 12 WHEN 'ALTA' THEN 6 WHEN 'MEDIA' THEN 3 ELSE 0 END), 0)
      INTO warning_penalty
      FROM warning w JOIN vw_warning_target t ON t.warning_id = w.id
     WHERE t.string_id = p_string_id
       AND w.type <> 'EFICIENCIA_BAIXA'
       AND w.generation_dt <= p_as_of
       AND (w.resolved_at IS NULL OR w.resolved_at > p_as_of);

    health_score := GREATEST(0, LEAST(100, round(
        100 * CASE WHEN sibling_ratio IS NULL THEN nominal_ratio ELSE 0.6 * sibling_ratio + 0.4 * nominal_ratio END
        - warning_penalty, 2)));
END;
$$;

CREATE OR REPLACE FUNCTION fn_relocation_candidates(p_company_id bigint, p_threshold numeric DEFAULT 70)
RETURNS TABLE (string_id uuid, string_code varchar, inverter_code varchar, company_unit_id uuid, unit_name varchar,
               manufacturer varchar, model varchar, installed_panels bigint, nominal_power_wp numeric,
               health_score numeric, health_calculated_at timestamptz, ranking bigint)
LANGUAGE sql STABLE AS $$
    WITH candidates AS (
        SELECT s.id, s.code, i.code AS inverter_code, cu.id AS unit_id, cu.name AS unit_name, pm.manufacturer, pm.model,
               c.installed_panels, c.nominal_power_wp, h.health_score, h.calculated_at
          FROM string s
          JOIN inverter i ON i.id = s.inverter_id
          JOIN company_unit cu ON cu.id = i.company_unit_id
          JOIN panel_model pm ON pm.id = s.panel_model_id
          JOIN vw_string_capacity c ON c.string_id = s.id
          JOIN vw_string_current_health h ON h.string_id = s.id
         WHERE cu.company_id = p_company_id AND s.status IN ('ATIVA', 'MANUTENCAO') AND h.health_score < p_threshold
    )
    SELECT id, code, inverter_code, unit_id, unit_name, manufacturer, model, installed_panels, nominal_power_wp,
           health_score, calculated_at, dense_rank() OVER (ORDER BY health_score)
      FROM candidates
     ORDER BY health_score, code;
$$;

CREATE OR REPLACE PROCEDURE pr_register_inverter(
    p_operator_id uuid,
    p_payload jsonb,
    INOUT p_inverter_id uuid DEFAULT NULL
)
LANGUAGE plpgsql AS $$
DECLARE
    v_unit      uuid;
    v_model_id  bigint;
    v_string    jsonb;
    v_string_id uuid;
    v_panel     jsonb;
    v_seq       integer := 0;
    v_count     integer;
BEGIN
    IF fn_role_of(p_operator_id) IS DISTINCT FROM 'OPERADOR' THEN
        RAISE EXCEPTION 'Somente um operador ativo cadastra inversor, strings e placas';
    END IF;
    SELECT company_unit_id INTO v_unit FROM employee WHERE id = p_operator_id;
    v_model_id := (p_payload ->> 'inverter_model_id')::bigint;
    IF jsonb_typeof(p_payload -> 'strings') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload -> 'strings') = 0 THEN
        RAISE EXCEPTION 'Informe ao menos uma string do inversor';
    END IF;

    INSERT INTO inverter (company_unit_id, inverter_model_id, code, serial_number, installed_at, created_by)
    VALUES (v_unit, v_model_id, p_payload ->> 'code', btrim(p_payload ->> 'serial_number'),
            (p_payload ->> 'installed_at')::date, p_operator_id)
    RETURNING id INTO p_inverter_id;

    FOR v_string IN SELECT value FROM jsonb_array_elements(p_payload -> 'strings') ORDER BY
        (value ->> 'mppt_number')::int, (value ->> 'entry_number')::int
    LOOP
        v_seq := v_seq + 1;
        v_count := jsonb_array_length(v_string -> 'panels');
        IF v_count IS NULL OR v_count = 0 THEN
            RAISE EXCEPTION 'A string na posição MPPT %/entrada % não tem placas', v_string ->> 'mppt_number', v_string ->> 'entry_number';
        END IF;
        INSERT INTO string (inverter_id, mppt_number, entry_number, code, panel_model_id, invoice_number,
                            acquisition_dt, unit_cost, purchased_qty, created_by)
        VALUES (p_inverter_id, (v_string ->> 'mppt_number')::smallint, (v_string ->> 'entry_number')::smallint,
                'STR-' || lpad(v_seq::text, 3, '0'), (v_string ->> 'panel_model_id')::bigint,
                btrim(v_string ->> 'invoice_number'), (v_string ->> 'acquisition_dt')::date,
                (v_string ->> 'unit_cost')::numeric, v_count, p_operator_id)
        RETURNING id INTO v_string_id;
        FOR v_panel IN SELECT value FROM jsonb_array_elements(v_string -> 'panels') LOOP
            INSERT INTO panel (string_id, serial_number, barcode)
            VALUES (v_string_id, btrim(v_panel ->> 'serial_number'), btrim(v_panel ->> 'barcode'));
        END LOOP;
    END LOOP;
END;
$$;

CREATE OR REPLACE PROCEDURE pr_activate_panel(
    p_barcode varchar,
    p_technician_id uuid,
    p_installation_dt date DEFAULT CURRENT_DATE
)
LANGUAGE plpgsql AS $$
DECLARE
    v_panel     panel%ROWTYPE;
    v_unit      uuid;
    v_installed date;
BEGIN
    IF fn_role_of(p_technician_id) IS DISTINCT FROM 'TECNICO' THEN
        RAISE EXCEPTION 'Somente um técnico ativo ativa placas';
    END IF;
    SELECT * INTO v_panel FROM panel WHERE barcode = btrim(p_barcode) FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Código de barras % não cadastrado pelo operador', p_barcode; END IF;
    SELECT i.company_unit_id, i.installed_at INTO v_unit, v_installed
      FROM string s JOIN inverter i ON i.id = s.inverter_id WHERE s.id = v_panel.string_id;
    IF v_unit IS DISTINCT FROM (SELECT company_unit_id FROM employee WHERE id = p_technician_id) THEN
        RAISE EXCEPTION 'A placa % pertence a outra filial', v_panel.serial_number;
    END IF;
    IF v_panel.operating_stats <> 'EM_ESTOQUE' THEN
        RAISE EXCEPTION 'A placa % já está %', v_panel.serial_number, v_panel.operating_stats;
    END IF;
    IF p_installation_dt > CURRENT_DATE OR p_installation_dt < v_installed THEN
        RAISE EXCEPTION 'Data de instalação deve estar entre a instalação do inversor (%) e hoje', v_installed;
    END IF;

    UPDATE panel SET operating_stats = 'OPERACIONAL', installation_dt = p_installation_dt,
                     activated_at = p_installation_dt + time '12:00', updated_at = p_installation_dt + time '12:00'
     WHERE id = v_panel.id;

    UPDATE string SET status = 'ATIVA', updated_at = CURRENT_TIMESTAMP
     WHERE id = v_panel.string_id AND status = 'EM_ESTOQUE'
       AND NOT EXISTS (SELECT 1 FROM panel WHERE string_id = v_panel.string_id AND operating_stats = 'EM_ESTOQUE');
END;
$$;

CREATE OR REPLACE PROCEDURE pr_deactivate_panel(
    p_barcode varchar,
    p_technician_id uuid,
    p_reason text
)
LANGUAGE plpgsql AS $$
DECLARE
    v_panel panel%ROWTYPE;
BEGIN
    IF fn_role_of(p_technician_id) IS DISTINCT FROM 'TECNICO' THEN
        RAISE EXCEPTION 'Somente um técnico ativo desativa placas';
    END IF;
    SELECT * INTO v_panel FROM panel WHERE barcode = btrim(p_barcode) FOR UPDATE;
    IF NOT FOUND OR v_panel.operating_stats IN ('EM_ESTOQUE', 'INATIVO') THEN
        RAISE EXCEPTION 'Placa % inexistente ou não instalada', p_barcode;
    END IF;
    UPDATE panel SET operating_stats = 'INATIVO', deactivated_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
     WHERE id = v_panel.id;
    UPDATE panel_status_history SET reason = p_reason
     WHERE id = (SELECT max(id) FROM panel_status_history WHERE panel_id = v_panel.id);
END;
$$;

CREATE OR REPLACE PROCEDURE pr_ingest_string_measurement(
    p_inverter_serial varchar,
    p_mppt_number smallint,
    p_entry_number smallint,
    p_measured_at timestamptz,
    p_power_w numeric,
    p_voltage_v numeric DEFAULT NULL,
    p_current_a numeric DEFAULT NULL,
    p_generated_energy_kwh numeric DEFAULT NULL,
    p_fault_code varchar DEFAULT NULL,
    p_data_source varchar DEFAULT 'SENSOR'
)
LANGUAGE plpgsql AS $$
DECLARE
    v_string_id uuid;
BEGIN
    SELECT s.id INTO v_string_id
      FROM string s JOIN inverter i ON i.id = s.inverter_id
     WHERE i.serial_number = p_inverter_serial AND s.mppt_number = p_mppt_number AND s.entry_number = p_entry_number
       AND s.status IN ('ATIVA', 'MANUTENCAO');
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Nenhuma string ativa no inversor % (MPPT %, entrada %)', p_inverter_serial, p_mppt_number, p_entry_number;
    END IF;
    INSERT INTO string_performance_measurement
        (string_id, measured_at, power_w, voltage_v, current_a, generated_energy_kwh, fault_code, data_source)
    VALUES (v_string_id, p_measured_at, p_power_w, p_voltage_v, p_current_a, p_generated_energy_kwh, p_fault_code, p_data_source)
    ON CONFLICT (string_id, measured_at) DO UPDATE
       SET power_w = EXCLUDED.power_w, voltage_v = EXCLUDED.voltage_v, current_a = EXCLUDED.current_a,
           generated_energy_kwh = EXCLUDED.generated_energy_kwh, fault_code = EXCLUDED.fault_code,
           data_source = EXCLUDED.data_source;
END;
$$;

CREATE OR REPLACE PROCEDURE pr_recalculate_string_health(
    p_company_unit_id uuid DEFAULT NULL,
    p_window_days integer DEFAULT 7,
    p_threshold numeric DEFAULT 70,
    p_as_of timestamptz DEFAULT CURRENT_TIMESTAMP
)
LANGUAGE plpgsql AS $$
DECLARE
    v_string record;
    v_calc   record;
BEGIN
    FOR v_string IN
        SELECT s.id, s.code, i.code AS inverter_code
          FROM string s JOIN inverter i ON i.id = s.inverter_id
         WHERE s.status IN ('ATIVA', 'MANUTENCAO')
           AND (p_company_unit_id IS NULL OR i.company_unit_id = p_company_unit_id)
    LOOP
        SELECT * INTO v_calc FROM fn_string_health_score(v_string.id, p_window_days, p_as_of);
        CONTINUE WHEN v_calc.health_score IS NULL;

        INSERT INTO string_health_history (string_id, calculated_at, window_days, sibling_ratio, nominal_ratio, warning_penalty, health_score)
        VALUES (v_string.id, p_as_of, p_window_days, v_calc.sibling_ratio, v_calc.nominal_ratio, v_calc.warning_penalty, v_calc.health_score)
        ON CONFLICT (string_id, calculated_at) DO UPDATE
           SET window_days = EXCLUDED.window_days, sibling_ratio = EXCLUDED.sibling_ratio, nominal_ratio = EXCLUDED.nominal_ratio,
               warning_penalty = EXCLUDED.warning_penalty, health_score = EXCLUDED.health_score;

        IF v_calc.health_score < p_threshold THEN
            IF NOT EXISTS (SELECT 1 FROM warning WHERE string_id = v_string.id AND type = 'EFICIENCIA_BAIXA' AND status <> 'RESOLVIDO') THEN
                INSERT INTO warning (string_id, type, severity, status, message, generation_dt)
                VALUES (v_string.id, 'EFICIENCIA_BAIXA',
                        CASE WHEN v_calc.health_score < 50 THEN 'CRITICA' WHEN v_calc.health_score < 60 THEN 'ALTA' ELSE 'MEDIA' END,
                        'ATIVO',
                        format('Saúde da string %s do inversor %s em %s%% (limiar %s%%)',
                               v_string.code, v_string.inverter_code, v_calc.health_score, p_threshold),
                        p_as_of);
            END IF;
        ELSE
            UPDATE warning w SET status = 'RESOLVIDO', resolved_at = GREATEST(p_as_of, w.generation_dt)
             WHERE w.string_id = v_string.id AND w.type = 'EFICIENCIA_BAIXA' AND w.status = 'ATIVO'
               AND NOT EXISTS (SELECT 1 FROM maintenance_register mr WHERE mr.warning_id = w.id);
        END IF;
    END LOOP;
END;
$$;

CREATE OR REPLACE PROCEDURE pr_report_panel_issue(
    p_barcode varchar,
    p_technician_id uuid,
    p_type varchar,
    p_severity varchar,
    p_message text,
    INOUT p_warning_id bigint DEFAULT NULL
)
LANGUAGE plpgsql AS $$
DECLARE
    v_panel_id bigint;
BEGIN
    IF fn_role_of(p_technician_id) IS DISTINCT FROM 'TECNICO' THEN
        RAISE EXCEPTION 'Somente um técnico ativo registra relato de campo';
    END IF;
    SELECT p.id INTO v_panel_id
      FROM panel p JOIN string s ON s.id = p.string_id JOIN inverter i ON i.id = s.inverter_id
     WHERE p.barcode = btrim(p_barcode)
       AND i.company_unit_id = (SELECT company_unit_id FROM employee WHERE id = p_technician_id);
    IF NOT FOUND THEN RAISE EXCEPTION 'Placa % não encontrada na filial do técnico', p_barcode; END IF;
    INSERT INTO warning (panel_id, type, severity, status, message, reported_by)
    VALUES (v_panel_id, upper(p_type), upper(p_severity), 'ATIVO', p_message, p_technician_id)
    RETURNING id INTO p_warning_id;
END;
$$;

CREATE OR REPLACE PROCEDURE pr_open_maintenance(
    p_warning_id bigint,
    p_operator_id uuid,
    p_technician_id uuid,
    p_maintenance_type_id bigint,
    p_due_date timestamptz DEFAULT NULL,
    p_estimated_cost numeric DEFAULT NULL,
    p_parent_maintenance_id bigint DEFAULT NULL,
    INOUT p_maintenance_id bigint DEFAULT NULL
)
LANGUAGE plpgsql AS $$
DECLARE
    v_warning   warning%ROWTYPE;
    v_string_id uuid;
BEGIN
    SELECT * INTO v_warning FROM warning WHERE id = p_warning_id FOR UPDATE;
    IF NOT FOUND OR v_warning.status <> 'ATIVO' THEN
        RAISE EXCEPTION 'Alerta % inexistente ou já tratado', p_warning_id;
    END IF;
    SELECT string_id INTO v_string_id FROM vw_warning_target WHERE warning_id = p_warning_id;

    INSERT INTO maintenance_register (parent_maintenance_id, warning_id, maintenance_type_id, technician_id, created_by, due_date, estimated_cost)
    VALUES (p_parent_maintenance_id, p_warning_id, p_maintenance_type_id, p_technician_id, p_operator_id, p_due_date, p_estimated_cost)
    RETURNING id INTO p_maintenance_id;

    UPDATE warning SET status = 'RECONHECIDO' WHERE id = p_warning_id;
    UPDATE string SET status = 'MANUTENCAO', updated_at = CURRENT_TIMESTAMP WHERE id = v_string_id AND status = 'ATIVA';
    UPDATE panel SET operating_stats = 'MANUTENCAO', updated_at = CURRENT_TIMESTAMP
     WHERE operating_stats = 'OPERACIONAL'
       AND ((v_warning.panel_id IS NOT NULL AND id = v_warning.panel_id)
            OR (v_warning.panel_id IS NULL AND string_id = v_string_id));
END;
$$;

CREATE OR REPLACE PROCEDURE pr_start_maintenance(p_maintenance_id bigint, p_technician_id uuid)
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE maintenance_register SET maintenance_status = 'EM_ANDAMENTO', technician_id = p_technician_id
     WHERE id = p_maintenance_id AND maintenance_status = 'ABERTA';
    IF NOT FOUND THEN RAISE EXCEPTION 'OS % não está aberta', p_maintenance_id; END IF;
END;
$$;

CREATE OR REPLACE PROCEDURE pr_release_after_maintenance(p_maintenance_id bigint)
LANGUAGE plpgsql AS $$
DECLARE
    v_string_id uuid;
    v_panel_id  bigint;
BEGIN
    SELECT t.string_id, w.panel_id INTO v_string_id, v_panel_id
      FROM maintenance_register mr JOIN warning w ON w.id = mr.warning_id JOIN vw_warning_target t ON t.warning_id = w.id
     WHERE mr.id = p_maintenance_id;
    IF EXISTS (SELECT 1 FROM maintenance_register mr JOIN vw_warning_target t ON t.warning_id = mr.warning_id
                WHERE t.string_id = v_string_id AND mr.id <> p_maintenance_id AND mr.maintenance_status IN ('ABERTA', 'EM_ANDAMENTO')) THEN
        UPDATE panel SET operating_stats = 'OPERACIONAL', updated_at = CURRENT_TIMESTAMP
         WHERE id = v_panel_id AND operating_stats = 'MANUTENCAO';
    ELSE
        UPDATE panel SET operating_stats = 'OPERACIONAL', updated_at = CURRENT_TIMESTAMP
         WHERE string_id = v_string_id AND operating_stats = 'MANUTENCAO';
        UPDATE string SET status = 'ATIVA', updated_at = CURRENT_TIMESTAMP WHERE id = v_string_id AND status = 'MANUTENCAO';
    END IF;
END;
$$;

CREATE OR REPLACE PROCEDURE pr_complete_maintenance(
    p_maintenance_id bigint,
    p_technician_id uuid,
    p_technical_report text,
    p_labor_cost numeric DEFAULT NULL
)
LANGUAGE plpgsql AS $$
DECLARE
    v_warning_id bigint;
BEGIN
    IF fn_role_of(p_technician_id) IS DISTINCT FROM 'TECNICO' THEN
        RAISE EXCEPTION 'Somente um técnico ativo conclui OS';
    END IF;
    UPDATE maintenance_register
       SET technician_id = p_technician_id, technical_report = p_technical_report, labor_cost = p_labor_cost,
           maintenance_status = 'CONCLUIDA', concluded_at = CURRENT_TIMESTAMP
     WHERE id = p_maintenance_id AND maintenance_status IN ('ABERTA', 'EM_ANDAMENTO')
    RETURNING warning_id INTO v_warning_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'OS ativa % não encontrada', p_maintenance_id; END IF;
    UPDATE warning SET status = 'RESOLVIDO', resolved_at = GREATEST(CURRENT_TIMESTAMP, generation_dt) WHERE id = v_warning_id;
    CALL pr_release_after_maintenance(p_maintenance_id);
END;
$$;

CREATE OR REPLACE PROCEDURE pr_cancel_maintenance(
    p_maintenance_id bigint,
    p_operator_id uuid,
    p_reason text
)
LANGUAGE plpgsql AS $$
DECLARE
    v_warning_id bigint;
    v_company    bigint;
BEGIN
    IF fn_role_of(p_operator_id) IS DISTINCT FROM 'OPERADOR' THEN
        RAISE EXCEPTION 'Somente um operador ativo cancela OS';
    END IF;
    SELECT mr.warning_id, t.company_id INTO v_warning_id, v_company
      FROM maintenance_register mr JOIN vw_warning_target t ON t.warning_id = mr.warning_id
     WHERE mr.id = p_maintenance_id AND mr.maintenance_status IN ('ABERTA', 'EM_ANDAMENTO');
    IF NOT FOUND THEN RAISE EXCEPTION 'OS ativa % não encontrada', p_maintenance_id; END IF;
    IF v_company IS DISTINCT FROM fn_company_of_employee(p_operator_id) THEN
        RAISE EXCEPTION 'OS de outra empresa';
    END IF;
    UPDATE maintenance_register
       SET maintenance_status = 'CANCELADA', cancelled_by = p_operator_id, cancelled_at = CURRENT_TIMESTAMP,
           cancellation_reason = p_reason
     WHERE id = p_maintenance_id;
    UPDATE warning SET status = 'ATIVO' WHERE id = v_warning_id AND status = 'RECONHECIDO';
    CALL pr_release_after_maintenance(p_maintenance_id);
END;
$$;

CREATE OR REPLACE PROCEDURE pr_register_access(
    p_email varchar,
    p_session_id uuid,
    p_ip_address inet,
    p_access_status varchar
)
LANGUAGE plpgsql AS $$
DECLARE
    v_employee uuid;
BEGIN
    SELECT id INTO v_employee FROM employee WHERE lower(email) = lower(btrim(p_email));
    IF v_employee IS NULL AND upper(p_access_status) = 'SUCESSO' THEN
        RAISE EXCEPTION 'Login com sucesso exige funcionário cadastrado';
    END IF;
    INSERT INTO access_log (employee_id, attempted_email, session_id, ip_address, access_status)
    VALUES (v_employee, CASE WHEN v_employee IS NULL THEN lower(btrim(p_email)) END, p_session_id, p_ip_address, upper(p_access_status))
    ON CONFLICT (session_id) DO NOTHING;
END;
$$;


-- ===== Indices =====
CREATE INDEX IF NOT EXISTS ix_company_unit_company ON company_unit (company_id, is_active);
CREATE INDEX IF NOT EXISTS ix_employee_unit_role ON employee (company_unit_id, role_id) WHERE is_active;
CREATE INDEX IF NOT EXISTS ix_inverter_unit ON inverter (company_unit_id, status);
CREATE INDEX IF NOT EXISTS ix_string_status ON string (status);
CREATE INDEX IF NOT EXISTS ix_panel_string_status ON panel (string_id, operating_stats);
CREATE INDEX IF NOT EXISTS ix_measurement_string_date ON string_performance_measurement (string_id, measured_at DESC);
CREATE INDEX IF NOT EXISTS ix_measurement_date ON string_performance_measurement (measured_at);
CREATE INDEX IF NOT EXISTS ix_health_history_string_date ON string_health_history (string_id, calculated_at DESC);
CREATE INDEX IF NOT EXISTS ix_warning_active_string ON warning (string_id, generation_dt DESC) WHERE status <> 'RESOLVIDO';
CREATE INDEX IF NOT EXISTS ix_warning_active_panel ON warning (panel_id, generation_dt DESC) WHERE status <> 'RESOLVIDO';
CREATE INDEX IF NOT EXISTS ix_maintenance_status_due ON maintenance_register (maintenance_status, due_date);
CREATE INDEX IF NOT EXISTS ix_maintenance_technician_date ON maintenance_register (technician_id, opening_dt DESC);
CREATE INDEX IF NOT EXISTS ix_mpart_part ON maintenance_part (part_id);
CREATE INDEX IF NOT EXISTS ix_internal_relocation_string ON suggested_internal_relocation (string_id, status);
CREATE INDEX IF NOT EXISTS ix_external_relocation_panel ON suggested_external_relocation (panel_id, status);
CREATE INDEX IF NOT EXISTS ix_access_employee_date ON access_log (employee_id, login_timestamp DESC);
CREATE INDEX IF NOT EXISTS ix_access_date ON access_log (login_timestamp);
CREATE INDEX IF NOT EXISTS ix_audit_panel_record ON audit.audit_panel (panel_id, operation_timestamp DESC);
CREATE INDEX IF NOT EXISTS ix_audit_maintenance_record ON audit.audit_maintenance_register (maintenance_id, operation_timestamp DESC);

-- ===== Notificacoes: gerada ao abrir OS (trigger) para o tecnico responsavel =====
CREATE OR REPLACE FUNCTION fn_notify_service_order_opened()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO notification (employee_id, maintenance_register_id, type, title, body)
    VALUES (NEW.technician_id, NEW.id, 'SERVICE_ORDER_OPENED',
            'Nova ordem de servico',
            'A OS #' || NEW.id || ' foi aberta para voce.' ||
            COALESCE(' Prazo: ' || to_char(NEW.due_date AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), ''))
    ON CONFLICT (maintenance_register_id, employee_id, type) DO NOTHING;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_notify_service_order_opened ON maintenance_register;
CREATE TRIGGER trg_notify_service_order_opened
AFTER INSERT ON maintenance_register
FOR EACH ROW EXECUTE FUNCTION fn_notify_service_order_opened();

COMMIT;


-- delta do patch de auditoria (idempotente)
BEGIN;

ALTER TABLE public.password_recovery ADD COLUMN IF NOT EXISTS masked_destination varchar(120);

DROP VIEW IF EXISTS vw_string_panels;
CREATE VIEW vw_string_panels AS
SELECT p.id AS panel_id, p.string_id, i.company_unit_id, s.code AS string_code, i.code AS inverter_code,
       p.serial_number, p.barcode, pm.manufacturer, pm.model, p.operating_stats, p.installation_dt, p.activated_at,
       h.health_score AS string_health_score,
       (SELECT count(*) FROM warning w WHERE w.panel_id = p.id AND w.status <> 'RESOLVIDO') AS active_panel_warnings,
       pm.pmax_w, pm.efficiency_pct, c.installed_panels AS string_installed_panels, s.purchased_qty AS string_purchased_qty
  FROM panel p
  JOIN string s ON s.id = p.string_id
  JOIN inverter i ON i.id = s.inverter_id
  JOIN panel_model pm ON pm.id = s.panel_model_id
  JOIN vw_string_capacity c ON c.string_id = s.id
  LEFT JOIN vw_string_current_health h ON h.string_id = s.id;

COMMIT;
